from PIL import Image

def analyze(path):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    # find small dark circular regions in the lower half that are isolated
    # threshold dark
    dark = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y][:3]
            if r < 50 and g < 50 and b < 50:
                dark[y][x] = True
    visited = [[False]*w for _ in range(h)]
    comps = []
    for y in range(h):
        for x in range(w):
            if not dark[y][x] or visited[y][x]:
                continue
            stack = [(x,y)]
            visited[y][x] = True
            pts = []
            while stack:
                cx,cy = stack.pop()
                pts.append((cx,cy))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        nx,ny = cx+dx, cy+dy
                        if 0<=nx<w and 0<=ny<h and dark[ny][nx] and not visited[ny][nx]:
                            visited[ny][nx] = True
                            stack.append((nx,ny))
            if 20 < len(pts) < 5000:
                xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
                comps.append((len(pts), sum(xs)/len(xs), sum(ys)/len(ys), min(xs), min(ys), max(xs), max(ys)))
    print(path, 'small dark comps', comps)

